{"function":"() => {
  function getLuminance(hexOrRgb) {
    let r, g, b;
    if (hexOrRgb.startsWith('#')) {
      const hex = hexOrRgb.replace('#', '');
      r = parseInt(hex.substring(0, 2), 16);
      g = parseInt(hex.substring(2, 4), 16);
      b = parseInt(hex.substring(4, 6), 16);
    } else {
      const match = hexOrRgb.match(/\d+/g);
      r = parseInt(match[0]);
      g = parseInt(match[1]);
      b = parseInt(match[2]);
    }
    const a = [r, g, b].map(v => {
      v /= 255;
      return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    });
    return a[0] * 0.2126 + a[1] * 0.7152 + a[2] * 0.0722;
  }

  function getContrast(rgb1, rgb2) {
    const l1 = getLuminance(rgb1);
    const l2 = getLuminance(rgb2);
    const lighter = Math.max(l1, l2);
    const darker = Math.min(l1, l2);
    return ((lighter + 0.05) / (darker + 0.05)).toFixed(2);
  }

  const types = ['admit', 'transit', 'leave', 'disch', 'pred', 'delay'];
  const results = {};
  types.forEach(type => {
    const el = document.querySelector('.ganttBarItem.' + type);
    if (el) {
      const cs = window.getComputedStyle(el);
      results[type] = {
        bg: cs.backgroundColor,
        color: cs.color,
        contrast: getContrast(cs.backgroundColor, cs.color),
        passesWCAG_AA_normal: parseFloat(getContrast(cs.backgroundColor, cs.color)) >= 4.5
      };
    }
  });
  return results;
}","pageId":1,"waitForStableDom":false}

