"  // Dynamically synchronize event status with actual movements in state where applicable
  const movementMap = new Map(movements.map((m) => [m.id, m]));
  for (const lane of lanes) {
    for (const ev of lane.events) {
      const live = movementMap.get(ev.id);
      if (!live) continue;
      const isPastOrPresent = now >= live.openedAt;
      if (live.stage === "moving" && isPastOrPresent) {
        ev.type = "transit";
      } else if (live.stage === "arrived") {
        ev.type = "disch";
      }
      if (units.length > 0 && live.acceptedUnitId && !ev.dest) {
        const destUnit = units.find((u) => u.id === live.acceptedUnitId);
        if (destUnit) {
          ev.dest = destUnit.name;
        }
      }
    }
  }

  return lanes;
}"

